fun formatShutterSpeed(exposureTimeNs: Long): String {
    if (exposureTimeNs <= 0) return "--"
    val seconds = exposureTimeNs / 1_000_000_000.0
    if (seconds >= 0.1) {
        val text = if (seconds >= 1.0) {
            String.format(java.util.Locale.US, "%.0f", seconds)
        } else {
            String.format(java.util.Locale.US, "%.2f", seconds).trimEnd('0').trimEnd('.')
        }
        return "${text}s"
    }
    val denominator = (1.0 / seconds).roundToInt()
    val approxSeconds = 1.0 / denominator
    return if (denominator > 1 && abs(approxSeconds - seconds) / seconds <= 0.1) {
        "1/${denominator}s"
    } else {
        String.format(java.util.Locale.US, "%.2f", seconds) + "s"
    }
}

